+package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;
+
+import org.springframework.stereotype.Component;
+
+import java.util.Locale;
+import java.util.Map;
+import java.util.Optional;
+import java.util.Set;
+
+@Component
+public class NativeTablePolicySelector {
+
+    private static final Map<NativeTablePolicy, Set<String>> SUPPORTED_FAMILIES = Map.of(
+            NativeTablePolicy.BORDERED_GRID, Set.of(
+                    "BOB", "BANK OF BARODA", "CBI", "CENTRAL BANK OF INDIA", "FEDERAL", "FEDERAL BANK",
+                    "IDBI", "INDIAN", "INDIAN BANK", "INDIAN OVERSEAS", "INDIAN OVERSEAS BANK", "IOB",
+                    "PNB", "PUNJAB NATIONAL BANK", "SBI", "STATE BANK OF INDIA", "UNION", "UNION BANK OF INDIA"),
+            NativeTablePolicy.BOX_GUIDED, Set.of(
+                    "AXIS", "AXIS BANK", "CITI", "CITIBANK", "DEUSTCHE", "DEUTSCHE", "DEUTSCHE BANK",
+                    "HDFC", "HDFC BANK", "ICICI", "ICICI BANK", "IDFC", "IDFC FIRST BANK", "INDUSIND",
+                    "INDUSIND BANK", "KOTAK", "KOTAK MAHINDRA BANK", "RBL", "RBL BANK",
+                    "STANDARD CHARTERED", "STANDARD CHARTERED BANK", "YES", "YES BANK"),
+            NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED, Set.of(
+                    "AHMEDNAGAR", "AHMEDNAGAR MERCHANTS CO OP BANK", "BANDHAN", "BANDHAN BANK",
+                    "GS MAHANAGAR CO OP BANK", "GS_MAHANAGAR_CO_OP_BANK", "SURYODAY SMALL FINANCE BANK LTD",
+                    "TJSB", "TJSB BANK"));
+
+    public Optional<NativeTablePolicy> select(String bankName) {
+        if (bankName == null || bankName.isBlank()) {
+            return Optional.empty();
+        }
