+                page.setTables(new LinkedHashMap<>());
+
+                Header header = findHeader(lines, policy);
+                if (header != null && lines.size() - header.lineIndex >= minimumRows(policy)) {
+                    Table table = toTable(lines.subList(header.lineIndex, lines.size()), header.columnStarts,
