+    private List<Line> toLines(List<TextPosition> positions, NativeTablePolicy policy) {
+        float lineTolerance = switch (policy) {
+            case BORDERED_GRID -> 0.035f;
+            case BOX_GUIDED -> 0.045f;
+            case TEXT_ALIGNED_ROW_SELECTED -> 0.055f;
