+        List<Glyph> glyphs = positions.stream()
+                .filter(position -> position.getUnicode() != null && !position.getUnicode().isEmpty())
+                .map(position -> new Glyph(position.getUnicode(), position.getXDirAdj() / POINTS_PER_INCH,
+                        position.getYDirAdj() / POINTS_PER_INCH, position.getWidthDirAdj() / POINTS_PER_INCH,
+                        position.getHeightDir() / POINTS_PER_INCH))
+                .sorted(Comparator.comparingDouble((Glyph glyph) -> glyph.y).thenComparingDouble(glyph -> glyph.x))
+                .toList();
+
+        List<List<Glyph>> groupedLines = new ArrayList<>();
+        for (Glyph glyph : glyphs) {
