+        Map<Integer, Map<Integer, TableCell>> rows = new LinkedHashMap<>();
+        int tableWordIndex = 1;
+        for (int rowIndex = 0; rowIndex < lines.size(); rowIndex++) {
+            Line line = lines.get(rowIndex);
+            Map<Integer, TableCell> cells = new LinkedHashMap<>();
+            float rowBottom = line.words.stream().map(word -> word.y2).max(Float::compareTo).orElse(line.y);
+            for (int columnIndex = 0; columnIndex < columnStarts.size(); columnIndex++) {
+                float left = boundaries.get(columnIndex);
+                float right = boundaries.get(columnIndex + 1);
+                List<Word> words = new ArrayList<>();
+                for (NativeWord nativeWord : line.words) {
+                    float center = (nativeWord.x1 + nativeWord.x2) / 2;
+                    if (center >= left && (center < right || columnIndex == columnStarts.size() - 1)) {
+                        words.add(toWord(nativeWord, pageNumber, tableWordIndex++));
+                    }
+                }
+                TableCell cell = new TableCell(left, line.y, right, line.y, right, rowBottom, left, rowBottom,
+                        1, 1, rowIndex, columnIndex, words, rowIndex == 0);
+                cells.put(columnIndex, cell);
+            }
+            rows.put(rowIndex, cells);
+        }
+
+        float top = lines.get(0).y;
+        float bottom = lines.get(lines.size() - 1).words.stream().map(word -> word.y2)
+                .max(Float::compareTo).orElse(lines.get(lines.size() - 1).y);
+        Table table = new Table();
+        table.setX1(pageMinX);
+        table.setY1(top);
+        table.setX2(pageMaxX);
+        table.setY2(top);
+        table.setX3(pageMaxX);
+        table.setY3(bottom);
+        table.setX4(pageMinX);
+        table.setY4(bottom);
+        table.setPageNumber(pageNumber);
+        table.setColType(new ArrayList<ColumnDataType>());
