+
+import java.io.File;
+import java.net.URISyntaxException;
+import java.util.Optional;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+class NativePdfTableExtractorTest {
+
+    private final NativeTablePolicySelector selector = new NativeTablePolicySelector();
+    private final NativePdfTableExtractor extractor = new NativePdfTableExtractor();
+
+    @Test
+    void selectsPoliciesOnlyForSupportedBankFamilies() {
+        assertEquals(NativeTablePolicy.BORDERED_GRID, selector.select("SBI").orElseThrow());
+        assertEquals(NativeTablePolicy.BOX_GUIDED, selector.select("HDFC").orElseThrow());
+        assertEquals(NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED,
+                selector.select("TJSB_BANK").orElseThrow());
+        assertTrue(selector.select("UNKNOWN_BANK").isEmpty());
+    }
+
+    @Test
+    void extractsStructuredRowsFromRepresentativeNativeFixtures() throws Exception {
+        assertStructuredTable("pdf-samples-latest/BOB/format1.pdf", NativeTablePolicy.BORDERED_GRID);
+        assertStructuredTable("pdf-samples-latest/HDFC/format1.pdf", NativeTablePolicy.BOX_GUIDED);
+        assertStructuredTable("pdf-samples-latest/AHMEDNAGAR/format1.pdf",
+                NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED);
+    }
+
+    private void assertStructuredTable(String resource, NativeTablePolicy policy) throws Exception {
+        Optional<DocumentExtractionResult> result = extractor.extract(resourceFile(resource), policy);
+        assertTrue(result.isPresent(), resource);
+        assertFalse(result.orElseThrow().getPages().values().stream()
+                .flatMap(page -> page.getTables().values().stream())
+                .filter(table -> table.getTotalRows() > 1 && table.getTotalColumns() > 3)
+                .findAny().isEmpty(), resource);
+    }
+
+    private File resourceFile(String resource) throws URISyntaxException {
+        return new File(getClass().getClassLoader().getResource(resource).toURI());
+    }
+}
